ksl4 = "".join("""

""".split())
cps4 = "".join("""

""".split())
print(len(ksl4), len(ksl4)%3, len(ksl4)//3-1)
print(len(cps4), len(cps4)%3, len(cps4)//3-1)

import re
comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]

def sites(seq, lo, hi):
    out=[]
    for strand,s in (("+",seq),("-",rc(seq))):
        L=len(seq)
        for m in re.finditer("(?=([ACGT]{21}GG))", s):
            i=m.start(); proto=m.group(1)[:20]; pam=m.group(1)[20:]
            # position of cut (3bp upstream of PAM) in sense coords
            if strand=="+":
                cut=i+17; start=i
            else:
                cut=L-(i+17); start=L-(i+20)
            if not (lo<=cut<=hi): continue
            gc=100*(proto.count("G")+proto.count("C"))/20
            out.append(dict(strand=strand,proto=proto,pam=m.group(1)[20:23],cut=cut,gc=gc,start=start))
    return out

def score(seq,other,lo,hi):
    res=[]
    for s in sites(seq,lo,hi):
        p=s["proto"]
        if "TTTT" in p: continue
        if not (40<=s["gc"]<=70): continue
        if re.search(r"(A{5}|C{5}|G{5}|T{5})",p): continue
        seed=p[-12:]
        # uniqueness within own gene and the partner gene (both strands)
        hits=sum(x.count(seed)+x.count(rc(seed)) for x in (seq,other))
        if hits>1: continue
        s["seed"]=seed; s["codon"]=s["cut"]//3+1
        res.append(s)
    return res

for name,seq,other in (("OsKSL4",ksl4,cps4),("OsCPS4",cps4,ksl4)):
    print("==",name,len(seq))
    cand=score(seq,other,120,620)
    cand.sort(key=lambda d:(-(d["proto"][0]=="G"), abs(d["gc"]-55)))
    for c in cand[:14]:
        print(f'{c["proto"]} {c["pam"]} {c["strand"]} cut@{c["cut"]} codon~{c["codon"]} GC={c["gc"]:.0f}')
